// CSD_RATIONALE_BEGIN
// DIAGNOSIS of attempt 24 (10.2%, 73.5% syntax):
//   ROOT CAUSE: Guidance without `<<>>` examples caused the model to write `int(formula)`
//   in free text (9 no_span_emitted), and RenderedEndsWith triggered on tiny intermediate
//   bare-variable spans (26 tiny_span_dominant). Removing the `<<int(formula)>>` example
//   from guidance was the primary regression.
//
// FIXES FOR ATTEMPT 25 (building from attempt 18, 49%/89.8%):
//
//   Fix 1 (CRITICAL): Restore guidance WITH `<<int(formula)>>` examples.
//     The model requires a concrete `<<int(...)>>` example in guidance to open the span.
//     Without it, the model writes `int(formula)` inline and never opens `<<`.
//
//   Fix 2 (API compliance): Use `RenderedEndsWith(generated, "<<")` + minPreludeSteps=50.
//     Replaces the `next == "<<"` API violation in the best attempt. minPreludeSteps=50
//     guards against guidance echoes in the first ~10-30 tokens.
//
//   Fix 3 (accuracy improvement): Remove `break` after first span close.
//     Evaluator uses the LAST visible span. Models often write intermediate partial spans
//     (e.g., `<<n1 * c1>>`) before the correct full formula (`<<int(n1*c1+n2*c2+c3)>>`).
//     With break (attempt 18): evaluator takes FIRST (partial) span → wrong.
//     Without break: evaluator takes LAST (complete) span → correct.
//     Guard: add `hasCompletedSpan` flag so force-open at prefixBudget is skipped
//     once a span has already been completed (prevents garbage second span from
//     overwriting a correct earlier span via evaluator's last-span policy).
//
//   Fix 4 (fewer unterminated spans): Increase maxSpanTokens from 22 to 30.
//     Complex GSM formulas like `int((t * currency * frac1) + ((total - t) * frac2))`
//     have ~18 tokens; with 30 they complete in the natural loop before
//     CloseSpanWithinBudget is needed.
//
// PARAMETERS (all from attempt 18 unless noted):
//   prefixBudget = maxSteps - 100 = 800
//   maxSpanTokens = 30  (was 22)
//   nearBudgetThreshold = 30
//   minPreludeSteps = 50  (new)
//   hasCompletedSpan = false  (new flag for force-open gate)
//   penaltyTokens = ["{","}", "**","^","\\"]  at 8.0
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Branch A (outside span, UnconstrainedStep, non-EOS, no << OR steps < minPreludeSteps):
//   insideConstrainedOut stays false → implication vacuously true.
//
// Branch B (outside span, UnconstrainedStep, non-EOS, RenderedEndsWith=true, steps >= 50):
//   EnterObservedConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by precondition. Preserved.
//
// Branch C (outside span, EOS): insideConstrainedOut unchanged (false) → vacuously true.
//
// Branch D (outside span, force-open at steps >= prefixBudget, !hasCompletedSpan):
//   OpenConstrainedSpan sets insideConstrainedOut := true, currentConstrainedOut := [].
//   parser.IsValidPrefix([]) by precondition. Preserved.
//
// Branch E (inside span, nearBudget <= 30 or spanTokens >= maxSpanTokens):
//   CloseSpanWithinBudget postcondition guarantees:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). Preserved.
//
// Branch F (inside span, CloseSpanIfComplete closed=true, no break):
//   insideConstrainedOut := ci = false; implication vacuously true.
//   Loop continues in unconstrained branch with insideConstrainedOut=false. Preserved.
//
// Branch G (inside span, CloseSpanIfComplete closed=false, next != EOS):
//   AdaptiveConstrainedStepWithPenalties hard-masks to parser-valid tokens + EOS.
//   AppendConstrainedToken: currentConstrainedOut := currentConstrainedOut + [next].
//   parser.IsValidPrefix holds by the constrained step contract. Preserved.
//
// Branch H (inside span, EOS from AdaptiveConstrained):
//   CloseSpanWithinBudget postcondition guarantees validity. Preserved.
//
// Invariant 2: progress  |generated| <= |generatedPrefix| + steps
//
// Branch A (UnconstrainedStep non-EOS, no <<): generated += [next] (+1), steps += 1. Preserved.
// Branch B (RenderedEndsWith true, steps >= 50): generated += [next] (+1), steps += 1.
//   EnterObservedConstrainedSpan: +0 cost, no append. |generated| = old+1 <= |gP|+steps. Preserved.
// Branch C (EOS): steps += 1, no append. Preserved.
// Branch D (OpenConstrainedSpan): appends exactly 1 token "<<", steps += 1. Preserved.
// Branch E (CloseSpanWithinBudget, budget = remainingBudget = maxSteps - steps_before):
//   |generated| grows by ≤ remainingBudget; steps grows by remainingBudget to maxSteps. Preserved.
// Branch F (CloseSpanIfComplete closed=true, no break): steps += 1, |generated| grows by ≤ 1 (for >>).
//   |generated| <= old+1 <= |gP| + (old_steps+1) = |gP| + steps. Preserved.
// Branch G (CloseSpanIfComplete closed=false, Adaptive + AppendConstrainedToken):
//   CloseSpanIfComplete: steps += 1, no visible append (closed=false path has no append).
//   AppendConstrainedToken: +0 cost, appends 1 token to generated.
//   Net: |generated| += 1, steps += 1. Preserved.
// Branch H (EOS inside span, CloseSpanWithinBudget):
//   rem = maxSteps - steps; steps grows by rem; |generated| grows by ≤ rem. Preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

// Guidance WITH <<int(formula)>> examples — model must see this format to open << spans.
// Using plain text for the examples (no raw << >> in this string would prevent the
// guidance itself from causing RenderedEndsWith false triggers, but the example
// format is critical; minPreludeSteps=50 guards against the first ~30 echo tokens).
var guidance: string := "Solve step by step. Use the variable names from the problem WITHOUT curly braces. Write the final answer as <<int(formula)>> where formula uses the actual variable names combined. Examples: <<int(n * p)>>, <<int(a + b - c * d)>>, <<int(total // count)>>. Use only +, -, *, /, //, %. No ** or ^.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var prefixBudget: nat := if maxSteps > 200 then maxSteps - 100 else (if maxSteps > 100 then maxSteps - 30 else maxSteps / 2);
var penaltyTokens: seq<Token> := ["{", "}", "**", "^", "\\"];
var spanTokens: nat := 0;
var maxSpanTokens: nat := 30;
var nearBudgetThreshold: nat := 30;
var minPreludeSteps: nat := 50;
var hasCompletedSpan: bool := false;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var remainingBudget := maxSteps - steps;
    // Force-open only if no span has completed yet (prevents garbage span from
    // overwriting a correct earlier span via evaluator's last-span policy).
    if steps >= prefixBudget && remainingBudget > 5 && !hasCompletedSpan {
      // Force open a constrained span for the final answer
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
      spanTokens := 0;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // RenderedEndsWith handles whitespace-prefixed or split << tokens (API compliant).
        // minPreludeSteps=50 guards against guidance echoes in the first ~10-30 tokens.
        if steps >= minPreludeSteps && RenderedEndsWith(generated, "<<") {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
          spanTokens := 0;
        }
      }
    }
  } else {
    // Inside constrained span
    var remainingBudget := maxSteps - steps;

    // Near budget end or span too long: force close with all remaining budget
    if remainingBudget <= nearBudgetThreshold || spanTokens >= maxSpanTokens {
      if remainingBudget > 0 {
        var sg, si, sc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remainingBudget
        );
        generated := sg;
        insideConstrainedOut := si;
        currentConstrainedOut := sc;
        steps := steps + remainingBudget;
      }
      break;
    }

    // Try to close if span is already a complete parse (costs 1 step)
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      hasCompletedSpan := true;
      // NO BREAK: evaluator takes the LAST visible span.
      // If model wrote an intermediate partial span first, the later (correct) full
      // formula span will be the one extracted. Without break, the loop continues
      // in the unconstrained branch and the model can generate the final complete span.
    } else {
      // Generate next constrained token with hard-mask and penalties on invalid chars
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStepWithPenalties(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 2.0,
        penaltyTokens, 8.0,
        6, eosToken
      );
      if next == eosToken {
        // EOS inside span: force close with remaining budget
        var rem := maxSteps - steps;
        if rem > 0 {
          var sg2, si2, sc2 := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem
          );
          generated := sg2;
          insideConstrainedOut := si2;
          currentConstrainedOut := sc2;
          steps := steps + rem;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        spanTokens := spanTokens + 1;
      }
    }
  }
}

cost := steps;

